/*
 * asound.c - libasound.so.2 for the guest: the sound card is the host's.
 *
 * There is no sound device in the kernel gx runs, and the real ALSA library
 * would look for one. This one has the part of ALSA a program uses to play
 * sound (one stream, two channels of 16 bits, the way Chromium asks for it)
 * and gives the samples to the host, through the functions gx_audio_* that
 * hostlib.c binds (see GX_LIST). Everything else ALSA has says that there is
 * nothing: no card, no mixer, no MIDI. Those are generated by the build from
 * what the program imports (see build-chromium.sh); only what plays is here.
 */
#include <errno.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* The host's (hostlib.c makes them): frames are two samples of 16 bits. */
long gx_audio_open(long rate, long channels);
long gx_audio_write(const void *frames, long count);   /* frames taken */
long gx_audio_queued(void);                            /* frames not played yet */
void gx_audio_drop(void);
void gx_audio_close(void);

#define FORMAT_S16_LE 2
#define STATE_PREPARED 2
#define STATE_RUNNING 3

struct pcm {
	int configured, running;
	long rate, buffer, period;
};

static int in_use;

int snd_pcm_open(struct pcm **pcm, const char *name, int stream, int mode)
{
	struct pcm *p;

	(void)name;
	(void)mode;
	/* Playback only, and one stream: programs that play several mix them. */
	if (stream != 0)
		return -ENOENT;
	if (__atomic_exchange_n(&in_use, 1, __ATOMIC_SEQ_CST))
		return -EBUSY;
	p = calloc(1, sizeof(*p));
	if (!p) {
		in_use = 0;
		return -ENOMEM;
	}
	*pcm = p;
	return 0;
}

int snd_pcm_close(struct pcm *pcm)
{
	if (pcm->configured)
		gx_audio_close();
	free(pcm);
	in_use = 0;
	return 0;
}

int snd_pcm_set_params(struct pcm *pcm, int format, int access, unsigned channels, unsigned rate,
		       int soft_resample, unsigned latency_us)
{
	(void)access;
	(void)soft_resample;
	if (format != FORMAT_S16_LE || channels != 2)
		return -EINVAL;
	if (!pcm->configured && gx_audio_open(rate, channels))
		return -EINVAL;
	pcm->configured = 1;
	pcm->rate = rate;
	pcm->buffer = (long)((uint64_t)latency_us * rate / 1000000);
	if (pcm->buffer < 1024)
		pcm->buffer = 1024;
	pcm->period = pcm->buffer / 4;
	return 0;
}

int snd_pcm_get_params(struct pcm *pcm, unsigned long *buffer_size, unsigned long *period_size)
{
	*buffer_size = pcm->buffer;
	*period_size = pcm->period;
	return 0;
}

long snd_pcm_avail_update(struct pcm *pcm)
{
	long room = pcm->buffer - gx_audio_queued();

	return room < 0 ? 0 : room;
}

int snd_pcm_delay(struct pcm *pcm, long *delay)
{
	(void)pcm;
	*delay = gx_audio_queued();
	return 0;
}

long snd_pcm_writei(struct pcm *pcm, const void *frames, unsigned long count)
{
	long room = snd_pcm_avail_update(pcm), done;

	if (!pcm->configured)
		return -EBADFD;
	if ((long)count > room)
		count = room;
	if (!count)
		return -EAGAIN;
	done = gx_audio_write(frames, count);
	if (done <= 0)
		return -EAGAIN;
	pcm->running = 1;
	return done;
}

long snd_pcm_readi(struct pcm *pcm, void *frames, unsigned long count)
{
	(void)pcm;
	(void)frames;
	(void)count;
	return -EBADFD;
}

int snd_pcm_state(struct pcm *pcm)
{
	return pcm->running ? STATE_RUNNING : STATE_PREPARED;
}

int snd_pcm_prepare(struct pcm *pcm)
{
	pcm->running = 0;
	return 0;
}

int snd_pcm_start(struct pcm *pcm)
{
	pcm->running = 1;
	return 0;
}

int snd_pcm_drop(struct pcm *pcm)
{
	if (pcm->configured)
		gx_audio_drop();
	pcm->running = 0;
	return 0;
}

int snd_pcm_drain(struct pcm *pcm)
{
	(void)pcm;
	return 0;
}

int snd_pcm_resume(struct pcm *pcm)
{
	(void)pcm;
	return 0;
}

int snd_pcm_recover(struct pcm *pcm, int err, int silent)
{
	(void)pcm;
	(void)silent;
	return err == -EAGAIN ? err : 0;
}

const char *snd_pcm_name(struct pcm *pcm)
{
	(void)pcm;
	return "default";
}

long snd_pcm_format_size(int format, unsigned long samples)
{
	return format == FORMAT_S16_LE ? (long)samples * 2 : -EINVAL;
}

const char *snd_strerror(int err)
{
	return strerror(err < 0 ? -err : err);
}

/* One card, with one device on it that plays: "default", the name programs
 * open when they have no reason to open another. */
int snd_card_next(int *card)
{
	*card = *card < 0 ? 0 : -1;
	return 0;
}

int snd_device_name_hint(int card, const char *iface, void ***hints)
{
	static char device[] = "default";

	(void)iface;
	*hints = calloc(2, sizeof(void *));
	if (!*hints)
		return -ENOMEM;
	if (card <= 0)
		(*hints)[0] = device;
	return 0;
}

/* The answers are the caller's to free. */
char *snd_device_name_get_hint(const void *hint, const char *id)
{
	(void)hint;
	if (!strcmp(id, "NAME"))
		return strdup("default");
	if (!strcmp(id, "DESC"))
		return strdup("Console");
	if (!strcmp(id, "IOID"))
		return strdup("Output");
	return NULL;
}

int snd_device_name_free_hint(void **hints)
{
	free(hints);
	return 0;
}
